import{_ as a,C as o,o as n,c as s,E as r,a2 as i}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"Concurrency Should Not Start With a Lock: The Smallest Safe Unit for Nested Callbacks","description":"","frontmatter":{"title":"Concurrency Should Not Start With a Lock: The Smallest Safe Unit for Nested Callbacks","date":"2026-08-12","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"How can a nested asynchronous tool runtime preserve ownership, cancellation and bounded failure without globally serializing independent sessions?","summary":"Safe callback concurrency starts with four boundaries—ownership, lifetime, capacity, and isolation—not with a choice of lock. Once work crosses a process boundary, those local boundaries must become a durably reconstructable protocol.","sources":"https://github.com/openai/codex/commit/ba2fb483197a6b428b8c6d999d192bb056c64ae7; research/analysis/Q-20260812-03-scoped-callback-concurrency.md; research/reading/Q-20260812-03-grpc-callback-ownership-cancellation.md","item_id":"Q-20260812-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-12-scoped-callback-concurrency.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-12-scoped-callback-concurrency.md","filePath":"en/engineering/2026-08-12-scoped-callback-concurrency.md","lastUpdated":1786537182000}'),c={name:"en/engineering/2026-08-12-scoped-callback-concurrency.md"};function l(d,e,h,u,p,b){const t=o("ArticleCover");return n(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-08-12-scoped-callback-concurrency.png",kicker:"Open-source Engineering · Daily Research",title:"Concurrency Should Not Start With a Lock: The Smallest Safe Unit for Nested Callbacks",summary:"Safe callback concurrency starts with four boundaries—ownership, lifetime, capacity, and isolation—not with a choice of lock. Once work crosses a process boundary, those local boundaries must become a durably reconstructable protocol.",version:"Q-20260812-03",status:"Daily Runtime V5 · 2026-08-12",languageHref:"/zh/engineering/2026-08-12-scoped-callback-concurrency",languageLabel:"中文"}),e[0]||(e[0]=i('<h1 id="concurrency-should-not-start-with-a-lock-the-smallest-safe-unit-for-nested-callbacks" tabindex="-1">Concurrency Should Not Start With a Lock: The Smallest Safe Unit for Nested Callbacks <a class="header-anchor" href="#concurrency-should-not-start-with-a-lock-the-smallest-safe-unit-for-nested-callbacks" aria-label="Permalink to &quot;Concurrency Should Not Start With a Lock: The Smallest Safe Unit for Nested Callbacks&quot;">​</a></h1><p>A remote session is halfway through a long operation when it calls back into a host tool. The callback is in flight when the user terminates the cell. At the same moment, an independent session submits a small query.</p><p>If the first design question is “which lock should protect this code?”, the two problems are easily coupled: a callback whose owner has disappeared keeps waiting, while the independent session stalls behind a large request. A better starting point is: <strong>who owns this callback, how long may it live, how much capacity may it consume, and can its wait cross a session boundary?</strong></p><p>The selected <a href="https://github.com/openai/codex/commit/ba2fb483197a6b428b8c6d999d192bb056c64ae7" target="_blank" rel="noreferrer">OpenAI Codex change</a> forwards gRPC code-mode callbacks to session delegates and exposes several concrete boundaries: cell ownership and enabled tools are checked before admission; a cancellation token links work to execution lifetime; pending delegate calls and recent callback IDs are bounded; and a test verifies that a large unary completion does not block an independent session. These facts support transferable engineering criteria. They do not establish cross-process exactly-once behavior, durable recovery, or rollback of external effects.</p><h2 id="turn-where-should-this-return-into-who-still-owns-it" tabindex="-1">Turn “where should this return?” into “who still owns it?” <a class="header-anchor" href="#turn-where-should-this-return-into-who-still-owns-it" aria-label="Permalink to &quot;Turn “where should this return?” into “who still owns it?”&quot;">​</a></h2><p>A callback ID can correlate a message. It cannot prove that the receiver still has authority to process it. A safe callback should also be bound to a session, an execution or cell, the enabled tool set, and the current cancellation scope.</p><p>The routing table is therefore more than <code>id -&gt; promise</code>. It behaves like a short-lived capability lease: a result may re-enter only while the execution that created it is still receptive and the requested tool remains inside its capability envelope. If the cell has ended, the session has been replaced, or authorization has been withdrawn, a late network response must not resurrect the old execution.</p><h2 id="a-safe-unit-needs-four-boundaries" tabindex="-1">A safe unit needs four boundaries <a class="header-anchor" href="#a-safe-unit-needs-four-boundaries" aria-label="Permalink to &quot;A safe unit needs four boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Boundary</th><th>What it constrains</th><th>Typical failure when missing</th></tr></thead><tbody><tr><td>Ownership</td><td>Which session and cell own the callback</td><td>A result enters the wrong execution, or an orphan is accepted</td></tr><tr><td>Lifetime</td><td>When to cancel, drain, or reject late results</td><td>Work survives termination or stale results revive</td></tr><tr><td>Capacity</td><td>Pending count, identifier, and payload limits</td><td>One session exhausts memory or scheduler capacity</td></tr><tr><td>Isolation</td><td>Whether one wait can block unrelated sessions</td><td>A large completion creates global head-of-line blocking</td></tr></tbody></table><p>Together, these boundaries define the smallest safe unit. A lock may protect state inside that unit; it cannot replace ownership validation, and it does not automatically provide cancellation, backpressure, or session isolation.</p><h2 id="a-global-lock-taxes-unrelated-work" tabindex="-1">A global lock taxes unrelated work <a class="header-anchor" href="#a-global-lock-taxes-unrelated-work" aria-label="Permalink to &quot;A global lock taxes unrelated work&quot;">​</a></h2><p>The simplest implementation keeps every callback in one global map behind one lock. It often looks correct under light tests, but it turns unrelated sessions into a shared failure domain: slow decoding, a large result, notification under lock, or cleanup can queue everyone behind one path.</p><p>A safer structure partitions state by session or execution, holds locks only long enough to locate and validate ownership, and moves payload transfer, delegate execution, and completion notification outside the critical section. The source&#39;s independent-session non-blocking test is worth preserving because it tests an isolation promise, not merely a throughput number.</p><h2 id="ended-is-not-one-state" tabindex="-1">“Ended” is not one state <a class="header-anchor" href="#ended-is-not-one-state" aria-label="Permalink to &quot;“Ended” is not one state&quot;">​</a></h2><p>A cell that is no longer running can mean at least two things. After normal completion, already-admitted notifications may need to drain so their results are observed. After forced termination, cancellation should propagate and stop outstanding work. Treating both cases as simple deletion either loses completed results or leaves orphaned tasks.</p><p>A shutdown protocol should therefore distinguish: reject new callbacks, drain admitted callbacks, cancel unfinished callbacks, reject late results, and release identity records. A bound on recently seen IDs is not cosmetic; it creates a finite window between duplicate detection, late delivery, and unbounded memory growth.</p><h2 id="local-ownership-stops-being-enough-across-a-process-boundary" tabindex="-1">Local ownership stops being enough across a process boundary <a class="header-anchor" href="#local-ownership-stops-being-enough-across-a-process-boundary" aria-label="Permalink to &quot;Local ownership stops being enough across a process boundary&quot;">​</a></h2><p>In-memory sessions, tokens, and callback IDs can protect a single process lifetime. They cannot answer identity after a restart. If the process dies after an external tool acts but before completion is recorded, the new runtime cannot know whether to retry, query, or compensate.</p><p>The answer is not to persist the local map verbatim. The protocol must be upgraded: give the execution occurrence and external effect stable identities, record verifiable admission and completion events, and require an idempotency key, read-back, or compensation path from the external tool. This is a further design hypothesis. The selected change does not prove those properties, so local concurrency safety must not be presented as distributed reliability.</p><h2 id="portable-review-criteria" tabindex="-1">Portable review criteria <a class="header-anchor" href="#portable-review-criteria" aria-label="Permalink to &quot;Portable review criteria&quot;">​</a></h2><p>Five counterexample tests expose the boundary: deliver a result after cell termination; return a very large completion from one session; exhaust pending callback capacity; reuse an old callback ID; and kill the process after an external effect but before its completion record.</p><p>The first four test ownership, lifetime, capacity, and isolation. The last reveals when the problem has become a durable protocol problem. An implementation that proves only the absence of data races, but cannot state the outcome of these tests, is not yet a safe agent callback runtime.</p><p>The durable conclusion is deliberately narrow: <strong>concurrency safety begins by making each callback an owned, expiring, bounded unit that cannot stall its neighbors. Once it crosses a process boundary, persistent facts must prove which occurrence it was.</strong></p><h3 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h3><ul><li><strong>What the source shows:</strong> the selected Codex path includes ownership checks, cancellation propagation, capacity bounds, and an independent-session non-blocking test. Same-change tests remain first-party evidence, not independent validation.</li><li><strong>What the source does not establish:</strong> cross-process recovery, exactly-once execution, and rollback of external effects.</li><li><strong>What this article proposes testing:</strong> stable execution identity, durable events, and external idempotency or read-back under fault injection and restart.</li></ul><p><strong>References:</strong></p><ul><li>OpenAI Codex, <a href="https://github.com/openai/codex/commit/ba2fb483197a6b428b8c6d999d192bb056c64ae7" target="_blank" rel="noreferrer"><code>ba2fb48</code> — Forward gRPC code-mode callbacks to session delegates</a>, code change and tests in the same commit.</li></ul>',27))])}const g=a(c,[["render",l]]);export{f as __pageData,g as default};
